create policy "books files read" on storage.objects for select to authenticated using (bucket_id = 'books');
create policy "books files admin insert" on storage.objects for insert to authenticated with check (bucket_id = 'books' and public.has_role(auth.uid(), 'admin'));
create policy "books files admin delete" on storage.objects for delete to authenticated using (bucket_id = 'books' and public.has_role(auth.uid(), 'admin'));